package com.meterflow.notifications;
import jakarta.validation.constraints.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;
@RestController @RequestMapping("/api/webhooks")public class WebhookController{private final WebhookRepository repo;private final WebhookDeliveryService delivery;public WebhookController(WebhookRepository r,WebhookDeliveryService d){repo=r;delivery=d;}public record Input(@NotBlank String customerId,@NotBlank String endpoint,@NotBlank String secret){}
@GetMapping @PreAuthorize("hasRole('ADMIN')")public List<Webhook> all(){return repo.findAll();}@PostMapping @PreAuthorize("hasRole('ADMIN')")public Webhook create(@Valid @RequestBody Input i){return repo.save(new Webhook(i.customerId(),i.endpoint(),i.secret()));}@GetMapping("/{id}/deliveries")@PreAuthorize("hasRole('ADMIN')")public List<WebhookDelivery> deliveries(@PathVariable UUID id){return delivery.all(id);}@PostMapping("/deliveries/{id}/replay")@PreAuthorize("hasRole('ADMIN')")public WebhookDelivery replay(@PathVariable UUID id){return delivery.replay(id);}}
